def accessible_projects(user: User) -> Select[tuple[Project]]:
    query = select(Project)
    if user.role == Role.OWNER:
        return query.where(Project.owner_id == user.id)
    if user.client_id is None:
        return query.where(false())  # a client user without a client sees nothing
    return query.where(Project.client_id == user.client_id)


def load_project(db: Session, user: User, project_id: int) -> Project:
    project = db.execute(accessible_projects(user).where(Project.id == project_id)).scalar_one_or_none()
    if project is None:
        raise not_found("Project")
    return project
